@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800&family=DM+Mono:wght@400;500&display=swap');
:root{--gold:#e5b85c;--paper:#e9e5d9;--muted:#9ba4ad;--line:#ffffff22;--panel:#0b111be8}
*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#070b11;color:var(--paper);font-family:'Barlow Condensed',sans-serif}
canvas{display:block;position:fixed;inset:0}
.grain{pointer-events:none;position:fixed;inset:0;z-index:2;opacity:.11;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.35'/%3E%3C/svg%3E")}
.vignette{position:fixed;inset:0;z-index:1;pointer-events:none;background:radial-gradient(ellipse at center,transparent 30%,#03060bc9 100%)}
.hud{position:fixed;z-index:4;inset:0;pointer-events:none}
.topbar{position:absolute;top:24px;left:30px;right:30px;display:flex;justify-content:space-between;align-items:flex-start}
.brand{font-size:12px;letter-spacing:.28em;color:var(--gold);font-weight:700}
.chapter{font:10px 'DM Mono';letter-spacing:.18em;color:#aab1b9;margin-top:5px}
.status{border:1px solid var(--line);background:#080d15a8;padding:10px 14px;font:10px 'DM Mono';letter-spacing:.12em;color:#d5d9db}
.status b{color:var(--gold);font-weight:400}
.objective{position:absolute;left:30px;top:100px;width:230px;border-left:2px solid var(--gold);padding:4px 0 5px 13px}
.eyebrow{font:9px 'DM Mono';letter-spacing:.2em;color:var(--gold);text-transform:uppercase}
.objective h2{font-size:20px;letter-spacing:.04em;margin:4px 0 3px;font-weight:600}
.objective p{font-size:14px;color:#aab0b5;margin:0;line-height:1.2}
.bottom{position:absolute;left:30px;bottom:25px;display:flex;gap:8px;align-items:center;color:#aeb5ba;font:10px 'DM Mono';letter-spacing:.1em}
.key{border:1px solid #ffffff3d;padding:5px 8px;color:#fff;background:#090e16aa}
.interact{position:absolute;left:50%;bottom:16%;transform:translateX(-50%);padding:9px 16px;border:1px solid #e5b85c88;background:#090e16dd;color:var(--paper);font-size:14px;letter-spacing:.08em;opacity:0;transition:opacity .2s}
.interact.show{opacity:1}
.toast{position:absolute;right:30px;bottom:27px;font:10px 'DM Mono';letter-spacing:.12em;color:var(--gold);text-align:right}
.dialogue{position:fixed;z-index:8;bottom:0;left:0;right:0;padding:24px max(28px,calc((100vw - 900px)/2)) 32px;background:linear-gradient(0deg,#070b11 70%,#070b11ee 88%,transparent);pointer-events:auto;display:none}
.dialogue.show{display:block}
.speaker{font:10px 'DM Mono';letter-spacing:.22em;color:var(--gold);margin-bottom:7px}
.line{font-size:clamp(20px,3vw,27px);line-height:1.16;max-width:820px}
.continue{margin-top:13px;font:10px 'DM Mono';letter-spacing:.16em;color:#9da5ad}
.titleScreen,.storyScreen,.endScreen{position:fixed;inset:0;z-index:10;display:flex;align-items:center;justify-content:center;background:#070b11}
.titleScreen{background:linear-gradient(90deg,#05080eeb,#05080e55),url('')}
.titleInner{width:min(980px,90vw);display:grid;grid-template-columns:1.1fr .9fr;gap:40px;align-items:center}
.titleCopy{position:relative;z-index:1}
.kicker{font:10px 'DM Mono';letter-spacing:.25em;color:var(--gold)}
h1{font-size:clamp(64px,11vw,132px);line-height:.77;letter-spacing:-.03em;margin:22px 0 20px;font-weight:800}
.titleCopy p{font-size:18px;line-height:1.3;color:#b1b8bd;max-width:410px}
.titleImage{height:min(68vh,550px);position:relative;background:radial-gradient(ellipse at 54% 76%,#25313a 0,#111922 31%,#080d14 64%);border:1px solid #ffffff17;overflow:hidden}
.moon{position:absolute;width:130px;height:130px;border-radius:50%;background:#c9c4aa;opacity:.75;top:11%;right:18%;box-shadow:0 0 70px #dfcf9e55}
.silhouette{position:absolute;bottom:-4%;left:25%;width:48%;height:80%;background:linear-gradient(90deg,#090d11,#171d21 45%,#080b10);clip-path:polygon(15% 100%,19% 46%,7% 31%,21% 39%,30% 6%,36% 0,43% 20%,52% 6%,61% 22%,71% 34%,89% 31%,77% 47%,81% 100%)}
.cityline{position:absolute;bottom:0;height:35%;width:100%;background:linear-gradient(transparent,#070a10 48%);}
.cityline:before{content:'';position:absolute;inset:20% 0 0;background:repeating-linear-gradient(90deg,#090d13 0 24px,transparent 24px 37px,#0b1017 37px 54px,transparent 54px 75px);clip-path:polygon(0 40%,8% 40%,8% 20%,17% 20%,17% 50%,26% 50%,26% 0,35% 0,35% 38%,48% 38%,48% 22%,57% 22%,57% 44%,66% 44%,66% 5%,77% 5%,77% 42%,89% 42%,89% 25%,100% 25%,100% 100%,0 100%)}
button{font-family:inherit;cursor:pointer}
.primary{border:0;background:var(--gold);color:#111;padding:13px 22px;font-size:13px;font-weight:700;letter-spacing:.15em;text-transform:uppercase;margin-top:12px}
.primary:hover{background:#f3ce7b}
.sub{font:10px 'DM Mono';color:#89929a;letter-spacing:.1em;margin-top:14px}
.storyScreen,.endScreen{display:none;background:radial-gradient(ellipse,#151d27,#070b11 67%)}
.storyScreen.show,.endScreen.show{display:flex}
.storyCard{width:min(750px,90vw);max-height:86vh;overflow-y:auto;padding:32px;border:1px solid #ffffff25;background:#080d15e8;box-shadow:0 24px 100px #000}
.storyCard::-webkit-scrollbar{width:5px}
.storyCard::-webkit-scrollbar-thumb{background:#e5b85c77}
.storyScreen{padding:18px}
.bottom{display:none}
.mobileControls{display:flex;bottom:max(18px,env(safe-area-inset-bottom));padding:0 24px}
.touchBtn:active,.actions button:active{background:#e5b85c55;transform:scale(.96)}
button{user-select:none;-webkit-user-select:none}
.storyDate{font:10px 'DM Mono';color:var(--gold);letter-spacing:.2em}
.storyCard h2{font-size:40px;margin:9px 0 15px;line-height:1}
.storyCard p{font-size:18px;color:#c1c5c6;line-height:1.42;margin:0 0 13px}
.storyCard p strong{color:#fff}
.quote{border-left:2px solid var(--gold);padding:4px 0 4px 15px;margin:16px 0;color:#e4e0d7;font-size:20px}
.storyControls{display:flex;justify-content:space-between;align-items:center;margin-top:20px}
.progress{font:10px 'DM Mono';color:#a1a8ad;letter-spacing:.15em}
.endScreen{text-align:center}
.endScreen h2{font-size:60px;margin:8px}
.endScreen p{font-size:18px;color:#aeb5bb;max-width:490px;margin:10px auto}
.mobileControls{display:none;position:fixed;z-index:5;inset:auto 0 18px;pointer-events:none;justify-content:space-between;padding:0 20px}
.pad{display:grid;grid-template-columns:44px 44px 44px;grid-template-rows:44px 44px 44px;gap:3px;pointer-events:auto}
.touchBtn{border:1px solid #ffffff3b;background:#08101bcc;color:#fff;font:14px 'DM Mono';border-radius:8px;touch-action:none}
.up{grid-column:2}
.left{grid-column:1;grid-row:2}
.down{grid-column:2;grid-row:2}
.right{grid-column:3;grid-row:2}
.actions{display:flex;align-items:end;gap:8px;pointer-events:auto}
.actions button{height:56px;min-width:58px;border-radius:50%;font-size:11px;color:#fff;border:1px solid #ffffff55;background:#08101bd9;touch-action:none}
.actions .act{border-color:#e5b85caa;color:var(--gold)}
@media(max-width:700px){.topbar{top:14px;left:16px;right:16px}
.objective{left:16px;top:75px;width:180px}
.objective h2{font-size:17px}
.objective p{font-size:12px}
.titleInner{grid-template-columns:1fr;gap:0}
.titleImage{position:absolute;inset:13% 0 0 24%;height:87%;opacity:.56;border:0}
.titleCopy{padding-top:30vh}
.titleCopy p{font-size:16px;max-width:300px}
.titleCopy h1{font-size:76px}
.status{padding:8px;font-size:8px}
.bottom{left:16px;bottom:15px;display:none}
.toast{right:16px;bottom:15px;font-size:9px}
.mobileControls{display:flex}
.interact{bottom:29%;font-size:12px}
.dialogue{padding:20px 20px 35px}
.line{font-size:20px}
.storyCard{padding:23px}
.storyCard h2{font-size:34px}
.storyCard p{font-size:16px}
.titleScreen{overflow:hidden}
}

