// location labels floating billboards
function label(text,x,y,z){const c=document.createElement('canvas');c.width=512;c.height=64;const ctx=c.getContext('2d');ctx.fillStyle='#e7e2d4';ctx.font='24px monospace';ctx.textAlign='center';ctx.fillText(text,256,40);const tex=new THREE.CanvasTexture(c);const spr=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,transparent:true,opacity:.72}));spr.position.set(x,y,z);spr.scale.set(4, .5,1);scene.add(spr)}
label('WAYNE SYSTEMS',-3.3,4.1,-9);label('SUIT BAY',4.3,6.25,-6);label('VEHICLE BAY',9,2.7,-8);label('LIFT TO THE ESTATE',0,7,9);
const keys={};let yaw=0,pitch=0,interactTarget=null,gameActive=false,dialogueQueue=[],dialogueBusy=false,toastTimer;
let collected=0;
const caveObjects=[...scene.children].filter(o=>o!==player&&!(o.isLight&&o.type==='HemisphereLight'));
const street=new THREE.Group();scene.add(street);street.visible=false;
const streetMat=mat(0x171b20,.9),brickMat=mat(0x252a30),windowMat=new THREE.MeshBasicMaterial({color:0xc38d4c}),enemyMat=mat(0x5a2527,.72),enemySkin=mat(0x9a7560),heroAttackMat=new THREE.MeshBasicMaterial({color:0xf2c66f,transparent:true,opacity:.8});
